//! A transport closed again once its peer has reconnected leaves the new transport in place.

use std::{sync::Arc, time::Duration};

use zenoh_core::ztimeout;
use zenoh_protocol::{
    core::{EndPoint, WhatAmI, ZenohIdProto},
    transport::close,
};

use crate::{DummyTransportEventHandler, TransportManager};

const TIMEOUT: Duration = Duration::from_secs(10);

fn manager(zid: ZenohIdProto, lowlatency: bool) -> TransportManager {
    TransportManager::builder()
        .zid(zid)
        .whatami(WhatAmI::Router)
        .unicast(
            TransportManager::config_unicast()
                .lowlatency(lowlatency)
                .qos(!lowlatency),
        )
        .build_test(Arc::new(DummyTransportEventHandler))
        .unwrap()
}

async fn listening(zid: ZenohIdProto, lowlatency: bool) -> (TransportManager, EndPoint) {
    let manager = manager(zid, lowlatency);
    let endpoint: EndPoint = format!("tcp/127.0.0.1:{}", zenoh_test::get_free_tcp_port())
        .parse()
        .unwrap();
    ztimeout!(manager.add_listener_unicast(endpoint.clone())).unwrap();
    (manager, endpoint)
}

/// The peer reconnects as a second manager with the same Zenoh id, as a restarted peer does,
/// so that its first transport's own closure cannot race the reconnection.
async fn a_transport_closed_again_after_its_peer_reconnected_leaves_the_new_one(lowlatency: bool) {
    let peer = ZenohIdProto::try_from([1]).unwrap();
    let (first, first_endpoint) = listening(peer, lowlatency).await;
    let (second, second_endpoint) = listening(peer, lowlatency).await;
    let connector = manager(ZenohIdProto::try_from([2]).unwrap(), lowlatency);

    let old = ztimeout!(connector.open_transport_unicast(first_endpoint)).unwrap();
    // A task that is to close the transport keeps it alive, as each of a router's tasks does.
    let kept = old.get_inner().unwrap();
    ztimeout!(old.close()).unwrap();
    let _new = ztimeout!(connector.open_transport_unicast(second_endpoint)).unwrap();

    ztimeout!(kept.close(close::reason::GENERIC)).unwrap();
    assert!(
        ztimeout!(connector.get_transport_unicast(&peer)).is_some(),
        "closing the closed transport again removed the new one"
    );

    ztimeout!(connector.close());
    ztimeout!(first.close());
    ztimeout!(second.close());
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_transport_closed_again_after_its_peer_reconnected_leaves_the_new_one_in_place() {
    a_transport_closed_again_after_its_peer_reconnected_leaves_the_new_one(false).await;
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn a_lowlatency_transport_closed_again_after_its_peer_reconnected_leaves_the_new_one_in_place(
) {
    a_transport_closed_again_after_its_peer_reconnected_leaves_the_new_one(true).await;
}
